from __future__ import annotations


DASHBOARD_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Git-Hunter | Security Operations</title>
<style>
:root{--bg:#07111f;--surface:#0d1b2e;--surface2:#11243c;--surface3:#162d49;--border:#21405f;--text:#e7f0fb;--muted:#91a7c0;--blue:#48a6ff;--cyan:#51d5e8;--green:#32d583;--amber:#f5b544;--red:#ff6678;--shadow:0 12px 30px #02071166}
*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;background:linear-gradient(135deg,#07111f,#09182a 48%,#07111f);color:var(--text);font:14px Inter,"Segoe UI",system-ui,sans-serif}
button,input,textarea,select{font:inherit}button{border:1px solid transparent;border-radius:5px;padding:9px 13px;background:var(--surface3);color:var(--text);cursor:pointer;font-weight:650}button:hover{border-color:var(--blue);background:#1b3c60}button.primary{background:#1672c9}button.danger{background:#7d293b}button.ghost{background:transparent;border-color:var(--border)}button.icon{padding:7px 10px;font-size:16px}
.app{display:grid;grid-template-columns:252px 1fr;min-height:100vh}.sidebar{background:#081629;border-right:1px solid var(--border);padding:20px 14px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;padding:4px 10px 24px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:8px;background:linear-gradient(145deg,#1688e5,#54d8ee);color:#07111f;font-weight:900}.brand strong{font-size:19px;letter-spacing:-.03em}.brand small{display:block;color:var(--muted);font-size:11px;margin-top:2px}.nav-label{padding:14px 12px 7px;color:#59728e;font-size:10px;text-transform:uppercase;letter-spacing:.14em}.nav{display:grid;gap:3px}.nav button{display:flex;align-items:center;gap:11px;width:100%;border:0;background:transparent;color:var(--muted);text-align:left}.nav button span{width:20px;text-align:center;color:#6d8bab}.nav button.active,.nav button:hover{background:#123456;color:#fff}.nav button.active span{color:var(--cyan)}.side-bottom{margin-top:auto;border-top:1px solid var(--border);padding:14px 10px;color:var(--muted);font-size:12px}.side-bottom strong{display:block;color:var(--green);margin-bottom:5px}
.main{min-width:0}.topbar{height:74px;padding:0 30px;border-bottom:1px solid var(--border);background:#09182acc;backdrop-filter:blur(10px);display:flex;align-items:center;justify-content:space-between;gap:20px;position:sticky;top:0;z-index:5}.title h1{font-size:20px;margin:0 0 4px}.title p{margin:0;color:var(--muted);font-size:12px}.top-actions{display:flex;gap:9px;align-items:center}.status{display:inline-flex;align-items:center;gap:7px;border-radius:999px;padding:6px 11px;background:#1a293c;color:var(--muted);font-size:12px}.status i{width:7px;height:7px;border-radius:50%;background:#73859a}.status.on{background:#123b32;color:#8ff0c0}.status.on i{background:var(--green);box-shadow:0 0 10px var(--green)}
.content{max-width:1600px;padding:28px 30px}.view{display:none}.view.active{display:block}.grid{display:grid;gap:14px}.metrics{grid-template-columns:repeat(6,minmax(115px,1fr));margin-bottom:18px}.two{grid-template-columns:1.35fr 1fr}.three{grid-template-columns:repeat(3,1fr)}.card{background:linear-gradient(145deg,var(--surface),#0b192c);border:1px solid var(--border);border-radius:8px;padding:18px;box-shadow:var(--shadow)}.card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:16px}.card h2{font-size:14px;margin:0}.eyebrow,.metric .label{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.13em}.metric .value{font-size:27px;font-weight:800;margin-top:8px}.good{color:var(--green)}.warn{color:var(--amber)}.bad{color:var(--red)}.blue{color:var(--blue)}.muted{color:var(--muted)}.hint{color:var(--muted);font-size:12px}.kv{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #1a3551}.kv:last-child{border:0}.kv strong{text-align:right}.bar{height:8px;background:#182e47;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--blue),var(--cyan));transition:width .3s}.repo-name{font-size:23px;font-weight:800;margin:5px 0 7px}.stage{color:var(--cyan);font-weight:750;letter-spacing:.08em;font-size:12px}.feed{max-height:300px;overflow:auto}.event{padding:10px 0;border-bottom:1px solid #1a3551}.event small{display:block;color:#6d849e;margin-top:4px}.empty{padding:30px;text-align:center;color:var(--muted)}
.table-wrap{overflow:auto}.alerts-table{width:100%;border-collapse:collapse;min-width:760px}.alerts-table th{text-align:left;color:#7892ad;text-transform:uppercase;letter-spacing:.09em;font-size:10px;padding:11px;border-bottom:1px solid var(--border)}.alerts-table td{padding:13px 11px;border-bottom:1px solid #17304a;vertical-align:top}.alerts-table tr:hover{background:#102942}.repo-cell strong{display:block}.repo-cell small{display:block;color:var(--muted);margin-top:4px}.badge{display:inline-flex;border-radius:999px;padding:4px 8px;font-size:11px;font-weight:750;background:#25344a;color:var(--muted)}.badge.high{background:#552533;color:#ffabb5}.badge.medium{background:#4b3b20;color:#ffd47e}.badge.safe{background:#123d32;color:#94efbd}.finding-count{color:var(--amber);font-weight:800}.toolbar{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:14px}.toolbar input{max-width:390px}.toolbar .spacer{flex:1}.drawer{position:fixed;inset:0;display:none;z-index:20;background:#02071199}.drawer.open{display:block}.drawer-panel{position:absolute;right:0;top:0;height:100%;width:min(650px,100%);overflow:auto;background:#0b1b2e;border-left:1px solid var(--border);box-shadow:-20px 0 50px #0008;padding:24px}.drawer-close{float:right}.incident-head{padding-bottom:18px;border-bottom:1px solid var(--border);margin-bottom:18px}.finding-card{background:#10243b;border:1px solid #244867;border-left:3px solid var(--amber);padding:13px;margin:10px 0;border-radius:5px}.finding-card code{display:block;color:var(--cyan);margin-bottom:6px}.code{background:#050e1a;border:1px solid #1c3b59;border-radius:6px;max-height:300px;overflow:auto;padding:14px;white-space:pre;font:12px ui-monospace,monospace;color:#c7daf7}.files{max-height:180px;overflow:auto}.file{padding:6px 0;border-bottom:1px solid #18334d;color:#abc3dc}
form{display:grid;gap:14px}.field{display:grid;gap:6px}.field label{font-weight:700}.field input,.field textarea,.field select,input,select,textarea{width:100%;padding:10px;border:1px solid var(--border);border-radius:5px;background:#081729;color:var(--text)}textarea{min-height:110px;resize:vertical}.form-actions{display:flex;gap:8px}.notice{padding:13px;background:#102d4b;border:1px solid #22547f;border-radius:6px;margin-bottom:14px;color:#b9d8f6}.toggle-row{display:flex;justify-content:space-between;gap:14px;padding:12px 0;border-bottom:1px solid #1a3551}
@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}.two,.three{grid-template-columns:1fr}}@media(max-width:720px){.app{display:block}.sidebar{position:static;padding:10px}.brand{padding-bottom:10px}.nav{display:flex;overflow:auto}.nav-label,.side-bottom{display:none}.topbar{padding:0 16px}.content{padding:18px 14px}.metrics{grid-template-columns:repeat(2,1fr)}.top-actions .ghost{display:none}}
</style>
</head>
<body>
<div class="app">
<aside class="sidebar">
  <div class="brand"><div class="brand-mark">GH</div><div><strong>Git-Hunter</strong><small>Security operations</small></div></div>
  <div class="nav-label">Workspace</div>
  <nav class="nav">
    <button class="active" data-view="overview"><span>◈</span>Command center</button>
    <button data-view="alerts"><span>!</span>Alerts & incidents <b id="nav-alerts" class="badge high" style="margin-left:auto">0</b></button>
    <button data-view="analysis"><span>◉</span>Live analysis</button>
    <button data-view="queue"><span>☷</span>Repository queue</button>
  </nav>
  <div class="nav-label">Operations</div>
  <nav class="nav">
    <button data-view="targets"><span>⌁</span>Discovery targets</button>
    <button data-view="inspector"><span>▣</span>Database inspector</button>
    <button data-view="settings"><span>⚙</span>System settings</button>
  </nav>
  <div class="side-bottom"><strong id="side-health">● Control plane online</strong><span>Local Kali deployment</span><br><span id="side-time">Waiting for telemetry</span></div>
</aside>
<section class="main">
<header class="topbar"><div class="title"><h1 id="page-title">Command center</h1><p id="page-subtitle">Monitor detections, discovery, and worker health</p></div><div class="top-actions"><button class="ghost" onclick="loadAll()">↻ Refresh</button><span id="system-pill" class="status"><i></i>Stopped</span><button class="primary" id="toggle">Start system</button></div></header>
<main class="content">
<section id="overview" class="view active">
  <div class="grid metrics">
    <div class="card metric"><div class="label">Pending</div><div class="value" id="m-pending">—</div></div>
    <div class="card metric"><div class="label">Open alerts</div><div class="value bad" id="m-alerts">—</div></div>
    <div class="card metric"><div class="label">Findings</div><div class="value warn" id="m-findings">—</div></div>
    <div class="card metric"><div class="label">Reviewed</div><div class="value good" id="m-review">—</div></div>
    <div class="card metric"><div class="label">Failed</div><div class="value bad" id="m-failed">—</div></div>
    <div class="card metric"><div class="label">API remaining</div><div class="value blue" id="m-api">—</div></div>
  </div>
  <div class="grid two">
    <div class="card"><div class="card-head"><div><div class="eyebrow">Live operation</div><h2 id="overview-operation">No repository active</h2></div><button class="ghost" data-view-link="analysis">Open analysis</button></div><div id="overview-current" class="empty">The worker is waiting for a repository.</div></div>
    <div class="card"><div class="card-head"><div><div class="eyebrow">Fleet health</div><h2>Runtime status</h2></div><span id="latency" class="badge">—</span></div><div class="kv"><span>Discovery spider</span><strong id="spider">—</strong></div><div class="kv"><span>Analysis worker</span><strong id="worker">—</strong></div><div class="kv"><span>Credentials</span><strong id="config-state">—</strong></div><div class="kv"><span>Last event</span><strong id="last-event">—</strong></div></div>
  </div>
  <div class="grid two" style="margin-top:14px"><div class="card"><div class="card-head"><div><div class="eyebrow">Triage queue</div><h2>Highest priority alerts</h2></div><button class="ghost" data-view-link="alerts">View all</button></div><div id="overview-alerts"></div></div><div class="card"><div class="card-head"><div><div class="eyebrow">Telemetry</div><h2>Activity stream</h2></div><button class="ghost" onclick="loadFeed()">Clear view</button></div><div id="feed" class="feed"></div></div></div>
</section>
<section id="alerts" class="view"><div class="card"><div class="card-head"><div><div class="eyebrow">Detection center</div><h2>Alerts & incidents</h2><span class="hint">Review findings with their exact source location and detection reason.</span></div><button class="ghost" onclick="loadQueue()">Refresh</button></div><div class="toolbar"><input id="alert-filter" placeholder="Search repository, file, or finding" oninput="renderQueue()"><select id="alert-sort" onchange="renderQueue()"><option value="score">Highest score</option><option value="findings">Most findings</option><option value="recent">Newest</option></select><span class="spacer"></span><span class="badge" id="alert-summary">0 alerts</span></div><div class="table-wrap"><table class="alerts-table"><thead><tr><th>Repository</th><th>Detection</th><th>Severity</th><th>Score</th><th>Action</th></tr></thead><tbody id="queue-list"></tbody></table></div></div></section>
<section id="analysis" class="view"><div id="analysis-empty" class="card empty"><h2>No active analysis</h2><p>Start the system or wait for the worker to claim a repository.</p></div><div id="analysis-live" style="display:none"><div class="grid two"><div class="card"><div class="eyebrow">Repository currently being checked</div><div class="repo-name" id="a-repo">—</div><a id="a-url" target="_blank" rel="noopener" class="muted">Open on GitHub ↗</a><p class="stage" id="a-stage">—</p><div class="bar"><i id="a-progress"></i></div><p class="muted" id="a-message"></p></div><div class="card"><div class="eyebrow">Analysis facts</div><div class="kv"><span>Files discovered</span><strong id="a-files">—</strong></div><div class="kv"><span>Current score</span><strong id="a-score">—</strong></div><div class="kv"><span>Queue ID</span><strong id="a-id">—</strong></div></div></div><div class="grid two" style="margin-top:14px"><div class="card"><div class="card-head"><h2>Code in memory</h2><span class="badge">Read-only</span></div><pre class="code" id="a-code">Waiting for source fetch…</pre></div><div class="card"><div class="card-head"><h2>Repository codebase</h2><span id="a-file-count" class="badge">0 files</span></div><div id="a-file-list" class="files"></div></div></div></div></section>
<section id="queue" class="view"><div class="card"><div class="card-head"><div><div class="eyebrow">Pipeline</div><h2>Repository queue</h2></div><button class="ghost" onclick="loadInspector()">Refresh</button></div><div class="toolbar"><select id="inspect-status" onchange="loadInspector()"><option value="pending">Pending</option><option value="scanning">Scanning</option><option value="completed">Completed</option><option value="failed">Failed</option><option value="safe">Marked safe</option><option value="malicious_confirmed">Confirmed malicious</option></select></div><div class="table-wrap"><table class="alerts-table"><thead><tr><th>ID</th><th>Repository</th><th>Status</th><th>Priority</th><th>Failure context</th></tr></thead><tbody id="inspector-table-body"></tbody></table></div><pre class="code" id="inspector-json" style="margin-top:14px">Select a record to inspect its data.</pre></div></section>
<section id="targets" class="view"><div class="card"><div class="card-head"><div><div class="eyebrow">Collection</div><h2>Discovery targets</h2></div><button class="primary" onclick="saveConfig()">Save targets</button></div><div class="grid two"><div class="field"><label>Search seed</label><input id="seed-query"><span class="hint">Use random for rotating CVE, PoC, and Python searches.</span></div><div class="field"><label>Repositories per cycle</label><input id="max-repos" type="number" min="1" max="100"></div></div><div class="field" style="margin-top:14px"><label>Target extensions</label><textarea id="extensions"></textarea><span class="hint">One extension per line. These files are fetched and analyzed in memory.</span></div></div></section>
<section id="inspector" class="view"><div class="card"><div class="card-head"><div><div class="eyebrow">Storage</div><h2>Database inspector</h2></div><button class="primary" onclick="loadInspector()">Refresh records</button></div><p class="hint">Inspect queue records, failure stages, and raw stored data.</p><div class="toolbar"><select id="inspect-status-alt" onchange="$('inspect-status').value=this.value;loadInspector()"><option value="failed">Failed repositories</option><option value="pending">Pending queue</option><option value="scanning">Currently scanning</option><option value="completed">Completed scans</option><option value="safe">Marked safe</option><option value="malicious_confirmed">Confirmed malicious</option></select></div><div class="table-wrap"><table class="alerts-table"><thead><tr><th>ID</th><th>Repository</th><th>Status</th><th>Priority</th><th>Failure context</th></tr></thead><tbody id="inspector-table-body-alt"></tbody></table></div></div></section>
<section id="settings" class="view"><div class="notice">Credentials remain in process memory. The dashboard is local-first and binds to loopback by default.</div><div class="card"><div class="card-head"><div><div class="eyebrow">Access</div><h2>Credentials & connections</h2></div><span id="cred-state" class="status">Not configured</span></div><form onsubmit="saveSetup(event)"><div class="field"><label>GitHub personal access token</label><input id="github-token" type="password" placeholder="Enter token"><span class="hint">Used for discovery and source fetching; never returned by the API.</span></div><div class="grid two"><div class="field"><label>Turso database URL</label><input id="turso-url" placeholder="libsql://…"><span class="hint">Leave blank for the local database.</span></div><div class="field"><label>Turso auth token</label><input id="turso-token" type="password" placeholder="Enter token"><span class="hint">Applied in memory when the connection changes.</span></div></div><div class="form-actions"><button class="primary">Save credentials</button><button type="button" class="ghost" onclick="loadSetup()">Discard</button></div></form></div><div class="card" style="margin-top:14px"><div class="card-head"><h2>Worker behavior</h2><span class="badge">Runtime</span></div><div class="field"><label>Scan interval (seconds)</label><input id="interval" type="number" min="1"></div><div class="form-actions" style="margin-top:14px"><button class="primary" onclick="saveConfig()">Save runtime settings</button><button class="danger" onclick="system('stop')">Emergency stop</button></div></div></section>
</main></section></div>
<div id="drawer" class="drawer" onclick="if(event.target===this)closeDrawer()"><aside class="drawer-panel"><button class="icon ghost drawer-close" onclick="closeDrawer()">×</button><div id="drawer-content"></div></aside></div>
<script>
const $=id=>document.getElementById(id),views=[...document.querySelectorAll('.view')],stageProgress={fetching:18,analyzing:52,enriching:82,completed:100,failed:100};let alertReports=[];
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function show(view){views.forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={overview:['Command center','Monitor detections, discovery, and worker health'],alerts:['Alerts & incidents','Investigate findings and review decisions'],analysis:['Live analysis','Follow the active worker operation'],queue:['Repository queue','Inspect pipeline state and failures'],targets:['Discovery targets','Control what the Wanderer collects'],inspector:['Database inspector','Inspect persisted queue records'],settings:['System settings','Credentials and runtime controls']};$('page-title').textContent=titles[view][0];$('page-subtitle').textContent=titles[view][1]}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-view-link]').forEach(b=>b.onclick=()=>show(b.dataset.viewLink));
async function get(path){const r=await fetch(path);if(!r.ok)throw Error('Request failed');return r.json()}
async function system(action){const r=await fetch('/api/system/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok){alert((await r.text()).replace(/<[^>]+>/g,''));return}await loadAll()}
async function loadStatus(){const s=await get('/api/system/status'),q=s.queue;$('m-pending').textContent=q.pending??0;$('m-alerts').textContent=q.alerts??0;$('m-findings').textContent=q.findings??0;$('m-review').textContent=q.reviewed??0;$('m-failed').textContent=q.failed??0;$('m-api').textContent=s.github_rate_limit_remaining??'—';$('nav-alerts').textContent=q.alerts??0;$('spider').textContent=s.spider_state;$('worker').textContent=s.worker_state;$('latency').textContent=s.turso_latency_ms+' ms';$('config-state').textContent=s.github_auth_failed?'GitHub token rejected':s.github_token_configured?'Ready':'Needs GitHub token';$('last-event').textContent=s.last_event||'—';$('side-time').textContent='Updated '+new Date().toLocaleTimeString();const on=s.spider_state==='running'||s.worker_state==='running';$('system-pill').className='status '+(on?'on':'');$('system-pill').innerHTML='<i></i> '+(on?'Running':'Stopped');$('toggle').textContent=on?'Stop system':'Start system';$('toggle').onclick=()=>system(on?'stop':'start');return s}
function findingText(f){return (f.file||'unknown file')+':'+(f.line||0)+' — '+(f.detail||f.kind||'finding')}
function severity(score){return score>=75?'high':score>=40?'medium':'safe'}
function rowHtml(r){const first=r.findings[0]||{},sev=severity(r.anomaly_score);return '<tr><td class="repo-cell"><strong>'+esc(r.full_name)+'</strong><small>Incident '+r.id+' · '+esc(r.status)+'</small></td><td><span class="finding-count">'+r.findings.length+'</span> finding(s)<small class="muted" style="display:block;margin-top:5px">'+esc(first.kind||'Finding recorded')+'</small></td><td><span class="badge '+sev+'">'+sev.toUpperCase()+'</span></td><td><strong>'+r.anomaly_score+'/100</strong></td><td><button class="ghost" onclick="openIncident('+r.id+')">Inspect</button></td></tr>'}
function renderQueue(){const filter=($('alert-filter')?.value||'').toLowerCase(),sort=$('alert-sort')?.value||'score';let rows=alertReports.filter(r=>(r.full_name+' '+r.findings.map(f=>findingText(f)).join(' ')).toLowerCase().includes(filter));rows.sort((a,b)=>sort==='findings'?b.findings.length-a.findings.length:sort==='recent'?b.id-a.id:b.anomaly_score-a.anomaly_score);$('queue-list').innerHTML=rows.length?rows.map(rowHtml).join(''):'<tr><td colspan="5"><div class="empty">No active incidents match this filter.</div></td></tr>';$('alert-summary').textContent=rows.length+' alert'+(rows.length===1?'':'s');$('overview-alerts').innerHTML=rows.slice(0,4).map(r=>'<div class="kv" style="cursor:pointer" onclick="openIncident('+r.id+')"><span><strong>'+esc(r.full_name)+'</strong><br><small class="muted">'+r.findings.length+' findings · '+esc(r.findings[0]?.kind||'finding')+'</small></span><span class="badge '+severity(r.anomaly_score)+'">'+r.anomaly_score+'</span></div>').join('')||'<div class="empty">No open alerts.</div>'}
async function loadQueue(){const rs=await get('/api/reports');alertReports=rs.map(r=>{let data={};try{data=JSON.parse(r.raw_json||'{}')}catch(error){}return {...r,findings:Array.isArray(data.findings)?data.findings:[]}});renderQueue()}
async function openIncident(id){const r=alertReports.find(item=>item.id===id)||await get('/api/reports/'+id);let data={};try{data=JSON.parse(r.raw_json||'{}')}catch(error){}const findings=Array.isArray(data.findings)?data.findings:[];$('drawer-content').innerHTML='<div class="eyebrow">Incident '+r.id+'</div><div class="incident-head"><h2>'+esc(r.full_name)+'</h2><p class="muted">'+esc(r.url)+'</p><div class="incident-meta"><span class="badge '+severity(r.anomaly_score)+'">'+severity(r.anomaly_score).toUpperCase()+'</span><span class="badge">'+r.anomaly_score+'/100</span><span class="badge">'+findings.length+' findings</span><span class="badge">'+esc(r.status)+'</span></div></div><h3>Why this was flagged</h3>'+findings.map(f=>'<div class="finding-card"><code>'+esc((f.file||'unknown file')+':'+(f.line||0))+'</code><strong>'+esc(f.kind||'finding')+'</strong><p class="muted">'+esc(f.detail||'The analyzer matched this behavior.')+'</p></div>').join('')+'<div class="form-actions" style="margin-top:20px"><button class="ghost" onclick="review('+r.id+',\'safe\');closeDrawer()">Mark safe</button><button class="danger" onclick="review('+r.id+',\'malicious_confirmed\');closeDrawer()">Confirm malicious</button></div>';$('drawer').classList.add('open')}
function closeDrawer(){$('drawer').classList.remove('open')}
function renderCurrent(c){const active=c&&c.repo_id;$('analysis-empty').style.display=active?'none':'block';$('analysis-live').style.display=active?'block':'none';if(!active){$('overview-operation').textContent='No repository active';$('overview-current').innerHTML='<div class="empty">The worker is waiting for a repository.</div>';return}$('overview-operation').textContent=c.full_name;$('a-repo').textContent=c.full_name;$('a-url').href='https://github.com/'+c.full_name;$('a-stage').textContent=(c.stage||'queued').toUpperCase();$('a-progress').style.width=(stageProgress[c.stage]||8)+'%';$('a-message').textContent=c.message||'';$('a-files').textContent=c.files_scanned??0;$('a-score').textContent=c.anomaly_score??'—';$('a-id').textContent=c.repo_id;$('a-code').textContent=c.source_preview||'Fetching source preview…';$('a-file-count').textContent=(c.source_paths||[]).length+' files';$('a-file-list').innerHTML=(c.source_paths||[]).map(f=>'<div class="file">'+esc(f)+'</div>').join('')||'<span class="muted">Waiting for repository tree…</span>';$('overview-current').innerHTML='<div class="repo-name">'+esc(c.full_name)+'</div><p class="stage">'+esc(c.message||c.stage)+'</p><div class="bar"><i style="width:'+(stageProgress[c.stage]||8)+'%"></i></div><p class="muted">'+(c.files_scanned||0)+' files discovered</p>'}
async function loadCurrent(){renderCurrent(await get('/api/system/current'))}
function showInspectorRecord(r){$('inspector-json').textContent=JSON.stringify(r,null,2);const alt=$('inspector-json-alt');if(alt)alt.textContent=JSON.stringify(r,null,2)}
async function loadInspector(){const status=$('inspect-status').value;const rows=await get('/api/db/inspect?status='+encodeURIComponent(status));const html=rows.length?rows.map(r=>'<tr onclick=\'showInspectorRecord('+JSON.stringify(r).replace(/'/g,'&#39;')+')\'><td>'+r.id+'</td><td class="repo-cell"><strong>'+esc(r.full_name)+'</strong><small>'+esc(r.url)+'</small></td><td><span class="badge">'+esc(r.status)+'</span></td><td>'+r.priority+'</td><td>'+esc(r.failure_stage||'—')+' '+esc(r.failure_reason||'')+'</td></tr>').join(''):'<tr><td colspan="5"><div class="empty">No records found.</div></td></tr>';$('inspector-table-body').innerHTML=html;if($('inspector-table-body-alt'))$('inspector-table-body-alt').innerHTML=html}
async function loadConfig(){const c=await get('/api/config');$('interval').value=c.scan_interval_seconds;$('extensions').value=c.target_extensions.join('\\n');$('seed-query').value=c.seed_query;$('max-repos').value=c.max_repositories_per_cycle}
async function saveConfig(){const r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scan_interval_seconds:Number($('interval').value),target_extensions:$('extensions').value.split('\\n').map(x=>x.trim()).filter(Boolean),seed_query:$('seed-query').value,max_repositories_per_cycle:Number($('max-repos').value)})});if(!r.ok){alert('Could not save runtime configuration');return}await loadConfig()}
async function loadSetup(){const s=await get('/api/setup'),local=!s.turso_database_url||s.turso_database_url.startsWith('file:'),text=s.github_auth_failed?'GitHub token rejected':s.github_token_configured?'GitHub token configured':'GitHub token missing';$('cred-state').textContent=text+(local?' · Local database':s.turso_auth_token_configured?' · Turso token configured':' · Turso token missing');$('turso-url').value=local?'':(s.turso_database_url||'')}
async function saveSetup(e){e.preventDefault();const p={};if($('github-token').value)p.github_token=$('github-token').value;if($('turso-token').value)p.turso_auth_token=$('turso-token').value;if($('turso-url').value)p.turso_database_url=$('turso-url').value;const r=await fetch('/api/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});if(!r.ok){alert((await r.text()).replace(/<[^>]+>/g,''));return}$('github-token').value='';$('turso-token').value='';await loadSetup();await loadAll()}
async function loadFeed(){const f=await get('/api/activity');$('feed').innerHTML=f.map(x=>'<div class="event">'+esc(x.message)+'<small>'+esc(x.time)+'</small></div>').join('')||'<div class="empty">No events yet.</div>'}
async function loadAll(){try{await Promise.all([loadStatus(),loadCurrent(),loadQueue(),loadFeed()])}catch(e){$('side-health').textContent='● Control plane unavailable';$('side-health').style.color='var(--red)';console.error(e)}}
loadConfig();loadSetup();loadAll();setInterval(loadAll,3000);
</script>
</body>
</html>"""
